INSERT INTO public.erp_ajuda_campo (chave, grupo, rotulo, o_que_preencher, para_que_serve, exemplo, erro_comum, ordem, rota, vertical, status)
VALUES
('projetos.desempenho.periodo_atalho','Desempenho','Período (Mês · Trimestre · Ano)','Escolha o recorte de tempo; "Personalizado" abre as duas datas.','Ganhas, perdidas, ticket, comissão e conversão só contam o que fechou dentro do período. O pipeline aberto não depende dele.','Ano','Olhar o Mês logo no início do mês e achar que não há vendas: use Trimestre ou Ano.',5,'/dashboard/projetos/desempenho','projetos','publicado'),
('projetos.desempenho.conversao','Desempenho','Conversão','Nada a preencher: calculado sozinho.','Ganhas ÷ (ganhas + perdidas) fechadas no período. Mostra quanto das negociações decididas virou venda.','2 ganhas e 3 perdidas = 40%','Esperar valor com oportunidades só abertas: sem fechamento aparece "—".',20,'/dashboard/projetos/desempenho','projetos','publicado'),
('projetos.desempenho.ganhas','Desempenho','Ganhas','Nada a preencher: vem das oportunidades marcadas como ganho.','Quantidade e valor das oportunidades ganhas com data de fechamento no período.','3 ganhas · R$ 120.000','Marcar como ganho sem preencher a data de fechamento.',30,'/dashboard/projetos/desempenho','projetos','publicado'),
('projetos.desempenho.perdidas','Desempenho','Perdidas','Nada a preencher: vem das oportunidades marcadas como perdido.','Quantidade e valor das oportunidades perdidas no período; o motivo aparece no bloco de perdas.','1 perdida · R$ 30.000','Perder a oportunidade sem informar o motivo.',40,'/dashboard/projetos/desempenho','projetos','publicado'),
('projetos.desempenho.ticket','Desempenho','Ticket médio','Nada a preencher: calculado sozinho.','Valor ganho no período dividido pelo número de ganhas.','R$ 40.000','Valor zerado quando as oportunidades ganhas estão sem valor de proposta.',50,'/dashboard/projetos/desempenho','projetos','publicado'),
('projetos.desempenho.comissao','Desempenho','Comissão gerada','Nada a preencher: usa o percentual de comissão do orçamento ligado à oportunidade.','Valor ganho × percentual de comissão do orçamento, só das ganhas do período.','R$ 120.000 × 3% = R$ 3.600','Aparecer R$ 0,00 porque o orçamento não tem percentual de comissão.',60,'/dashboard/projetos/desempenho','projetos','publicado'),
('projetos.desempenho.pipeline','Desempenho','Pipeline aberto','Nada a preencher: soma das oportunidades ainda em andamento.','Valor da proposta (ou estimado) de tudo que não foi ganho nem perdido, independente do período.','12 oport. · R$ 800.000','Pipeline R$ 0,00 com oportunidades abertas: faltou preencher o valor estimado.',70,'/dashboard/projetos/desempenho','projetos','publicado'),
('projetos.desempenho.velocidade','Desempenho','Velocidade','Nada a preencher: calculado sozinho.','Média de dias entre criar a oportunidade e fechá-la como ganha, no período.','18 d','"—" quando não houve ganha no período.',80,'/dashboard/projetos/desempenho','projetos','publicado'),
('projetos.desempenho.funil','Desempenho','Funil por fase','Nada a preencher: cada barra é uma fase do funil de vendas.','Mostra quantas oportunidades e quanto valor estão em cada fase; ganho e perdido contam só o período.','Proposta: 5 · R$ 300.000','Fase vazia não é erro: significa que nenhuma oportunidade está nela.',90,'/dashboard/projetos/desempenho','projetos','publicado'),
('projetos.desempenho.ranking','Desempenho','Ranking de vendedores','Nada a preencher: visível só para gestor.','Compara cada vendedor em oportunidades, ganhas, conversão, ticket e comissão no período.','Ana: 4 ganhas · 50%','Oportunidade sem responsável cai em "(sem responsável)".',100,'/dashboard/projetos/desempenho','projetos','publicado'),
('projetos.desempenho.perdas','Desempenho','Perdas por motivo','Nada a preencher: o motivo vem do que foi informado ao perder a oportunidade.','Mostra por que as vendas não fecharam, ordenado pelo valor perdido.','Preço: R$ 50.000 · 2','"(sem motivo)" alto: peça para registrar o motivo ao perder.',110,'/dashboard/projetos/desempenho','projetos','publicado')
